import csv
import io


# The supplier renamed ``available`` in the v2 feed. Accept both the old
# spelling and the common v2 spelling variants so a schema change does not
# silently break the sync at runtime.
_AVAILABILITY_COLUMNS = {
    "available",
    "availableqty",
    "availablequantity",
    "qtyavailable",
    "quantityavailable",
}


def _availability_column(fieldnames):
    for name in fieldnames or ():
        normalized = "".join(character.lower() for character in name if character.isalnum())
        if normalized in _AVAILABILITY_COLUMNS:
            return name
    raise ValueError("stock feed is missing an availability column")


def parse_feed(text):
    rows = csv.DictReader(io.StringIO(text))
    quantity_column = _availability_column(rows.fieldnames)
    if not rows.fieldnames or "sku" not in rows.fieldnames:
        raise ValueError("stock feed is missing the sku column")
    return {
        row["sku"].strip(): int(row[quantity_column])
        for row in rows
    }
